action.query:
query Query($where: InventoryCountDetailWhereInput, $orderBy: [InventoryCountDetailOrderByInput!], $first: Int, $after: String) {
  inventoryCountDetail(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        adjustment
        approved
        complete
        contentCount
        duplicate
        ejected
        note
        inventoryData
        actualQuantity {
          value
          unitId
          unit {code id}
        }
        expectedQuantity {
          value
          unitId
          unit {code id}
        }
        count {
          id
          number
        }
        expectedLocation {
          id
          name
        }
        actualLocation {
          id
          name
        }
        inventory {
          id
          number
        }
        inventoryTransaction {
          id
          number
        }
      }
    }
  }
}
